def skinny_table_entry(M: int, N: int, K: int, dtype: str) -> Optional[tuple]:
    """The table entry of a shape (None outside the table: min(M, N) > 1023)."""
    s, g = min(int(M), int(N)), max(int(M), int(N))
    bs = int(math.floor(math.log2(max(1, s))))
    if bs > 9:
        return None
    bg = min(15, max(7, int(math.floor(math.log2(max(1, g))))))
    bk = min(15, max(6, int(math.floor(math.log2(max(1, int(K)))))))
    dt = "f16" if dtype in ("fp16", "f16") else "bf16"
    return SKINNY_TABLE.get((dt, int(M <= N), bs, bg, bk))


def skinny_table_plan(arch: str, M: int, N: int, K: int, dtype: str):
    """The table's SkinnyGemmSpec for a shape (``None`` when no entry)."""
    from dataclasses import replace

    from ...instances.common.gemm_skinny import SkinnyGemmSpec

    if arch not in ("gfx950", "gfx942"):
        return None
    e = skinny_table_entry(M, N, K, dtype)
    if e is None:
        return None
    ma, na, wm, wn, wk, kc, pf, tw, _r = e
    K = int(K)
    spec = SkinnyGemmSpec(
        dtype="fp16" if dtype in ("fp16", "f16") else "bf16",
        wave_m_atoms=ma,
        wave_n_atoms=na,
        warp_m=wm,
        warp_n=wn,
        warp_k=wk,
        kc=kc,
        prefetch=pf,
        red_sync="sc1",
        kalign=8 if K % 8 == 0 else (2 if K % 2 == 0 else 1),
    )
    split = 1
    if tw:
        tiles = -(-int(M) // spec.tile_m) * -(-int(N) // spec.tile_n)
        steps = -(-K // spec.step_k)
        split = max(
            1, min(256, round(tw / max(1, tiles * spec.waves)), max(1, steps // wk))
        )
    return replace(spec, split=split, red_unroll=8 if split >= 16 else 4)
